import sys; sys.path.insert(0,"/workspace/social/posts"); from build10 import build
B=r'''<style>.box p,.box li{font-size:20.5px;line-height:1.3}.box h2{font-size:26px;margin-bottom:5px}.tbl{font-size:18.5px}.tbl th,.tbl td{padding:4px 6px}.iq ol{font-size:19px;line-height:1.3}.pill{font-size:15.5px}.grid{gap:11px}.handle{bottom:-12px}.box{padding:10px 12px}.tagline{font-size:19px;margin-bottom:6px}</style>
<div class="title">🔐 HxGN EAM Role Security <span class="badge">CHEAT SHEET</span></div>
<div class="tagline">One login, many roles: switch between purchasing, scheduling and admin views without logging out. (Infor EAM 11.6.1 Role Security brief)</div>
<div class="grid">
<div class="box c1"><h2>1. What &amp; why</h2><ul><li>One <b>User ID</b> with multiple <b>Roles</b> in the same Organization</li><li>Each Role = its own permissions, menus, screens, page layout</li><li>No more duplicate logins per job function</li><li>Available from Infor EAM <b>11.6.1</b></li></ul></div>
<div class="box c2"><h2>2. Before vs after</h2><ul><li><b>OFF:</b> User + Org → exactly <b>one</b> User Group (1:1)</li><li><b>ON:</b> User → Role → User Group + Org (1:many)</li><li>Same Org can appear more than once on the User's Organization tab</li><li>Biggest win: users doing several functions in one Org</li></ul></div>
<div class="box c3"><h2>3. Enable it</h2><ul><li>Install parameter <b>ROLESECU</b> = ON</li><li>Not shipped — the admin must <b>create</b> it</li><li>Needs <b>MULTIORG = YES</b> (multi-org security)</li><li>MULTIORG off → no Switch Roles button</li></ul></div>
<div class="box c4"><h2>4. ROLESECU effect</h2><table class="tbl"><tr><th></th><th>Not ON</th><th>ON</th></tr><tr><td>Role field</td><td>always * , protected</td><td>editable</td></tr><tr><td>LOVs</td><td>all user's Orgs</td><td>Orgs of current Role</td></tr><tr><td>Switch Roles</td><td>hidden</td><td>shown</td></tr><tr><td>Menu + layout</td><td>User's group</td><td>Role's group</td></tr></table></div>
<div class="box c5"><h2>5. Role Setup screen</h2><ul><li>Each Role links a <b>User Group</b> + an <b>Organization</b></li><li>Product permissions: base app, mobile apps…</li><li><b>Role Limits</b>: Requisition, Invoice, PO + approval limits</li><li>Permissions still read from User → Organization tab, via the Role's group</li></ul></div>
<div class="box c6"><h2>6. Default Role *</h2><ul><li>System role, always available</li><li>Shipped with the <b>R5</b> User Group under the * Organization</li><li>Role * = menus + layout from the User record's group</li><li>So switching ON doesn't break existing users</li></ul></div>
<div class="box c7"><h2>7. DEFORG rule</h2><ul><li>Every Role needs access to the default Org (<b>DEFORG</b>)</li><li>Add a non-DEFORG row → EAM auto-inserts a DEFORG row (same Role + group)</li><li>Delete the DEFORG row → remove the Role's other rows first</li></ul></div>
<div class="box c8"><h2>8. User experience</h2><ul><li><b>Switch Roles</b> in System Links → pick a Role, no logout</li><li><b>About</b> link shows the current Role (even when OFF)</li><li>Reports only include data for the current Role's Orgs</li></ul></div>
<div class="box c1" style="grid-column:1 / span 2"><h2>9. Disabling Role Security</h2><ul><li>Set ROLESECU to any value other than ON</li><li>Blocked while any user has the <b>same Org more than once</b> on the Organization tab: clean those rows first</li><li>After disabling, every user's Role resets to the default <b>*</b></li></ul></div>
<div class="bottom">
<div class="box" style="border-color:#1a5f7a"><h2 style="color:#1a5f7a">10a. Flow</h2><div class="flow" style="flex-wrap:wrap;row-gap:4px"><span class="pill">MULTIORG=YES</span><span class="arr">→</span><span class="pill">ROLESECU=ON</span><span class="arr">→</span><span class="pill">Role Setup</span><span class="arr">→</span><span class="pill">Assign on User</span><span class="arr">→</span><span class="pill">Switch Roles</span></div></div>
<div class="box iq"><h2>10b. Consultant tips</h2><ol><li>Check MULTIORG before creating ROLESECU</li><li>Design Roles by job function, not by person</li><li>Replace duplicate per-function logins</li><li>Plan the duplicate-Org cleanup before disabling</li></ol></div>
<div class="box" style="border-color:#2d8a5a"><h2 style="color:#2d8a5a">10c. Key points</h2><ul><li>Create ROLESECU</li><li>Role = Group + Org</li><li>* = old behavior</li></ul></div>
</div></div>'''
build("/workspace/social/posts/2026-10-18-linkedin-eam-role-security",B,1350,"Rahul Kumar")
